/**
 * Query condition. The condition consists of
 * `data`, logic operator and a modifier.
 */
class QueryCondition implements \JsonSerializable
{
    public function __construct(
        public QueryConditionLogic $logic,
        public QueryConditionModifier $modifier,
        public QueryConditionData $data
    ) {}

    public function jsonSerialize(): mixed
    {
        return [
            "logic" =>
                $this->logic instanceof \JsonSerializable
                    ? $this->logic->jsonSerialize()
                    : $this->logic,
