                $this->modifier instanceof \JsonSerializable
                    ? $this->modifier->jsonSerialize()
                    : $this->modifier,
            "data" =>
                $this->data instanceof \JsonSerializable
                    ? $this->data->jsonSerialize()
                    : $this->data,
        ];
    }
}

/** Query condition data */
class QueryConditionData implements \JsonSerializable
{
    private function __construct(private string $tag, private mixed $value) {}

    /**
     * Distance from the search origin. Takes count comparison
     * (e.g. Equal, GreaterThan).
     */
    public static function Distance(CountComparison $value): self
    {
        return new self("Distance", $value);
    }
    /** Is the current element an edge? I.e. `id < 0`. */
    public static function Edge(): self
    {
        return new self("Edge", null);
    }
    /**
     * Tests number of edges (from+to) of the current element.
     * Only nodes will pass. Self-referential edges are
     * counted twice. Takes count comparison
     * (e.g. Equal, GreaterThan).
     */
    public static function EdgeCount(CountComparison $value): self
    {
        return new self("EdgeCount", $value);
    }
    /**
     * Tests the number of outgoing edges (from) of the
     * current element. Takes count comparison
     * (e.g. Equal, GreaterThan).
     */
    public static function EdgeCountFrom(CountComparison $value): self
    {
        return new self("EdgeCountFrom", $value);
    }
    /**
     * Tests the number of incoming edges (to) of the
     * current element. Takes count comparison
     * (e.g. Equal, GreaterThan).
     */
    public static function EdgeCountTo(CountComparison $value): self
    {
        return new self("EdgeCountTo", $value);
    }
    /** Tests if the current id is in the list of ids. */
    public static function Ids(array $value): self
    {
        return new self("Ids", $value);
    }
    /**
     * Tests if the current element has a property `key`
     * with a value that evaluates true against `comparison`.
     */
    public static function KeyValue(KeyValueComparison $value): self
    {
        return new self("KeyValue", $value);
    }
    /** Test if the current element has **all** of the keys listed. */
    public static function Keys(array $value): self
    {
        return new self("Keys", $value);
    }
    /** Is the current element a node? I.e. `0 < id`. */
    public static function Node(): self
    {
        return new self("Node", null);
    }
    /** Nested list of conditions (equivalent to brackets). */
    public static function Where(array $value): self
    {
        return new self("Where", $value);
    }

    public function getTag(): string
    {
        return $this->tag;
    }

    public function getValue(): mixed
    {
        return $this->value;
    }

    public function jsonSerialize(): mixed
    {
        if ($this->value === null) {
            return $this->tag;
        }
        return [
            $this->tag =>
                $this->value instanceof \JsonSerializable
                    ? $this->value->jsonSerialize()
                    : $this->value,
        ];
    }
}

/** Logical operator for query conditions */
enum QueryConditionLogic: string
{
    /** Logical AND (&&) */
    case And = "And";
    /** Logical Or (||) */
    case Or = "Or";
}

/** Query condition modifier */
enum QueryConditionModifier: string
{
    /** No modifier */
    case None = "None";
    /**
     * Continues the search beyond the current element
     * if the condition being modified passes. Only controls
     * traversal, does not affect element selection.
     */
    case Beyond = "Beyond";
    /** Reversal of the result (equivalent to `!`). */
    case Not = "Not";
    /**
     * Stops the search beyond the current element
     * if the condition being modified passes. Only controls
     * traversal, does not affect element selection.
     */
    case NotBeyond = "NotBeyond";
}

