 * select queries.
 */
class QueryIds implements \JsonSerializable
{
    private function __construct(private string $tag, private mixed $value) {}

    /** List of [`QueryId`]s */
    public static function Ids(array $value): self
    {
        return new self("Ids", $value);
    }
    /** Search query */
    public static function Search(SearchQuery $value): self
    {
        return new self("Search", $value);
    }

    public function getTag(): string
    {
        return $this->tag;
    }

    public function getValue(): mixed
    {
        return $this->value;
    }

    public function jsonSerialize(): mixed
    {
        if ($this->value === null) {
            return $this->tag;
        }
        return [
            $this->tag =>
                $this->value instanceof \JsonSerializable
                    ? $this->value->jsonSerialize()
                    : $this->value,
        ];
    }
}

/**
 * Universal database result. Successful
 * execution of a query will always yield
 * this type. The `result` field is a numerical
 * representation of the result while the
 * `elements` are the list of `DbElement`s
 * with database ids and properties (key-value pairs).
 */
class QueryResult implements \JsonSerializable
{
    public function __construct(public int $result, public array $elements) {}

    public function jsonSerialize(): mixed
    {
        return [
            "result" => $this->result,
            "elements" => array_map(
                fn($v) => $v instanceof \JsonSerializable
                    ? $v->jsonSerialize()
                    : $v,
                $this->elements
            ),
        ];
    }
}

