/** Query to search for ids in the database following the graph. */
class SearchQuery implements \JsonSerializable
{
    public function __construct(
        public SearchQueryAlgorithm $algorithm,
        public QueryId $origin,
        public QueryId $destination,
        public int $limit,
        public int $offset,
        public array $order_by,
        public array $conditions,
        public bool $reverse
    ) {}

    public function jsonSerialize(): mixed
    {
        return [
            "algorithm" =>
                $this->algorithm instanceof \JsonSerializable
                    ? $this->algorithm->jsonSerialize()
                    : $this->algorithm,
            "origin" =>
                $this->origin instanceof \JsonSerializable
                    ? $this->origin->jsonSerialize()
                    : $this->origin,
            "destination" =>
                $this->destination instanceof \JsonSerializable
                    ? $this->destination->jsonSerialize()
                    : $this->destination,
            "limit" => $this->limit,
            "offset" => $this->offset,
            "order_by" => array_map(
                fn($v) => $v instanceof \JsonSerializable
                    ? $v->jsonSerialize()
                    : $v,
                $this->order_by
            ),
            "conditions" => array_map(
                fn($v) => $v instanceof \JsonSerializable
                    ? $v->jsonSerialize()
                    : $v,
                $this->conditions
            ),
            "reverse" => $this->reverse,
        ];
    }
}

/** Search algorithm to be used */
enum SearchQueryAlgorithm: string
{
    /**
     * Examines each distance level from the search origin in full
     * before continuing with the next level. E.g. when starting at
     * a node it first examines all the edges and then nodes they lead
     * to.
     */
    case BreadthFirst = "BreadthFirst";
    /**
     * Examines maximum distance it can reach following every element.
     * E.g. when starting at a node it will go `edge -> node -> edge -> node`
     * until it reaches dead end or encounters already visited element.
     */
    case DepthFirst = "DepthFirst";
    /**
     * Bypasses the graph traversal and inspects only the index specified
     * as the first condition (key).
     */
    case Index = "Index";
    /**
     * Examines all elements in the database disregarding the graph structure
     * or any relationship between the elements.
     */
    case Elements = "Elements";
}

